package autorouter_setting

import (
	_ "embed"
	"math"

	"github.com/QuantumNous/new-api/common"
	"github.com/QuantumNous/new-api/pkg/autorouter"
	"github.com/QuantumNous/new-api/setting/config"
)

// taskModelsJSON is generated by go run ./pkg/autorouter/modelrank/cmd/modelrank
// from public leaderboards; its rank_sources, task_models and default_models
// serve until the first scheduled ranking refresh writes the options.
//
//go:embed task_models.json
var taskModelsJSON []byte

// AutoRouterSetting configures resolution of the "auto" model. Option keys are
// autorouter_setting.<json name>; map and list values are stored as JSON. The
// jev endpoint, key and model come from the JEV_ENDPOINT, JEV_API_KEY and
// JEV_MODEL environment variables.
type AutoRouterSetting struct {
	Enabled          bool `json:"enabled"`
	JevTimeoutMs     int  `json:"jev_timeout_ms"`
	MaxRunes         int  `json:"max_runes"`
	PreviousMaxRunes int  `json:"previous_max_runes"`
	CacheTTLSeconds  int  `json:"cache_ttl_seconds"`
	// TaskModels maps a jev task type to base model names in preference order.
	// A model supports an effort when the effort-suffixed name (e.g.
	// gpt-5-high) is usable; the bare name is its provider default effort.
	TaskModels    map[string][]string `json:"task_models"`
	DefaultModels []string            `json:"default_models"`
	// RankRefreshEnabled regenerates task_models and default_models from
	// public leaderboards every RankRefreshIntervalHours; the OpenRouter key
	// comes from the OPENROUTER_API_KEY environment variable. A refresh
	// overwrites manual edits to the two lists.
	RankRefreshEnabled       bool `json:"rank_refresh_enabled"`
	RankRefreshIntervalHours int  `json:"rank_refresh_interval_hours"`
	// RankSources records the snapshot date of every source behind the
	// current lists and when they were generated.
	RankSources map[string]string `json:"rank_sources"`
	// DifficultyEfforts maps difficulty rungs 1..n to reasoning efforts.
	DifficultyEfforts      []string `json:"difficulty_efforts"`
	DefaultEffort          string   `json:"default_effort"`
	UpgradeBenefit         float64  `json:"upgrade_benefit"`
	MinTaskTypeProbability float64  `json:"min_task_type_probability"`
	ContinuationTaskChange float64  `json:"continuation_task_change"`
	// TaskScores maps a task type to the leaderboard score of each of its
	// models, the quality side of the quality/price choice. It is generated
	// together with TaskModels and overwritten by every ranking refresh.
	TaskScores map[string]map[string]float64 `json:"task_scores"`
	// CostLambda is the largest score a model may give up for being cheaper, and
	// ScoreTieDelta the score gap below which two models count as equally good
	// and the cheaper one wins. The pick never falls below the best score by
	// more than their sum; zero for both means the best-scored model always wins.
	CostLambda    float64 `json:"cost_lambda"`
	ScoreTieDelta float64 `json:"score_tie_delta"`
}

var autoRouterSetting = AutoRouterSetting{
	JevTimeoutMs:             5000,
	MaxRunes:                 2000,
	PreviousMaxRunes:         500,
	CacheTTLSeconds:          7200,
	RankRefreshEnabled:       true,
	RankRefreshIntervalHours: 24,
	DifficultyEfforts:        []string{"low", "medium", "high", "xhigh"},
	DefaultEffort:            "medium",
	UpgradeBenefit:           0.5,
	MinTaskTypeProbability:   0.5,
	ContinuationTaskChange:   0.5,
	CostLambda:               0.05,
	ScoreTieDelta:            0.02,
}

func init() {
	if err := common.Unmarshal(taskModelsJSON, &autoRouterSetting); err != nil {
		panic("autorouter_setting: task_models.json: " + err.Error())
	}
	// 内嵌文件里每个任务类型的 evidence 带着各模型的榜单分，就是 task_scores 的初始值。
	var seed struct {
		Evidence map[string][]struct {
			Model string  `json:"model"`
			Score float64 `json:"score"`
		} `json:"evidence"`
	}
	if err := common.Unmarshal(taskModelsJSON, &seed); err != nil {
		panic("autorouter_setting: task_models.json evidence: " + err.Error())
	}
	autoRouterSetting.TaskScores = make(map[string]map[string]float64, len(seed.Evidence))
	for task, entries := range seed.Evidence {
		scores := make(map[string]float64, len(entries))
		for _, entry := range entries {
			scores[entry.Model] = entry.Score
		}
		autoRouterSetting.TaskScores[task] = scores
	}
	config.GlobalConfig.Register("autorouter_setting", &autoRouterSetting)
}

func GetAutoRouterSetting() *AutoRouterSetting {
	return &autoRouterSetting
}

func (s *AutoRouterSetting) Policy() autorouter.Policy {
	return autorouter.Policy{
		TaskModels:             s.TaskModels,
		DefaultModels:          s.DefaultModels,
		DifficultyEfforts:      s.DifficultyEfforts,
		DefaultEffort:          s.DefaultEffort,
		UpgradeBenefit:         s.UpgradeBenefit,
		MinTaskTypeProbability: s.MinTaskTypeProbability,
		ContinuationTaskChange: s.ContinuationTaskChange,
		TaskScores:             s.TaskScores,
		CostLambda:             scoreWeight(s.CostLambda),
		ScoreTieDelta:          scoreWeight(s.ScoreTieDelta),
	}
}

// scoreWeight 把榜单分尺度（0 到 1）上的权重限制在 [0, 1]。
// strconv.ParseFloat 接受 "NaN"，而 NaN 会让质量/成本选择的比较全部为假，必须在这里挡住。
func scoreWeight(value float64) float64 {
	if math.IsNaN(value) {
		return 0
	}
	return min(max(value, 0), 1)
}
